import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer parser = new StringTokenizer(in.readLine());

        long N = Long.parseLong(parser.nextToken());
        long M = Long.parseLong(parser.nextToken());
        long L = Long.parseLong(parser.nextToken());
        long R = Long.parseLong(parser.nextToken());

        long area = N * M;
        long length = R - L + 1;
        long value = modPow(length, area);

        if (area % 2 == 1) {
            out.println(value);
        } else if (length % 2 == 0) {
            out.println(value * ((MOD + 1) / 2) % MOD);
        } else {
            out.println((value + 1) * ((MOD + 1) / 2) % MOD);
        }

        in.close();
        out.close();
    }

    private static long modPow(long base, long exp) {
        long result = 1L;
        long factor = base;
        while (exp > 0L) {
            if ((exp & 1L) == 1L) {
                result = result * factor % MOD;
            }
            factor = factor * factor % MOD;
            exp >>= 1;
        }
        return result;
    }
}
